mapper.update:
INSERT INTO J_직원_발령이력 (아이디, 발령유형, 발령일, 이전부서코드, 신규부서코드, 사유, 등록일시) SELECT #{userId}, N'부서이동', CAST(GETDATE() AS date), (SELECT TOP 1 부서코드 FROM J_직원_부서배치 WHERE 직원아이디 = #{userId} AND 종료일 IS NULL AND 주부서여부 = 1), t.부서코드, #{reason,jdbcType=NVARCHAR}, GETDATE() FROM J_직원_부서배치 t WHERE t.배치PK = #{assignPk} AND t.직원아이디 = #{userId} AND t.종료일 IS NULL AND t.주부서여부 = 0;
UPDATE J_직원_부서배치 SET 주부서여부 = 0 WHERE 직원아이디 = #{userId} AND 종료일 IS NULL AND 주부서여부 = 1 AND EXISTS (SELECT 1 FROM J_직원_부서배치 t WHERE t.배치PK = #{assignPk} AND t.직원아이디 = #{userId} AND t.종료일 IS NULL AND t.주부서여부 = 0);
UPDATE J_직원_부서배치 SET 주부서여부 = 1 WHERE 배치PK = #{assignPk} AND 직원아이디 = #{userId} AND 종료일 IS NULL AND 주부서여부 = 0;
UPDATE J_직원_재직 SET 주부서코드 = (SELECT 부서코드 FROM J_직원_부서배치 WHERE 배치PK = #{assignPk}), 지점명 = (SELECT b.지점명 FROM J_부서 b WHERE b.부서코드 = (SELECT 부서코드 FROM J_직원_부서배치 WHERE 배치PK = #{assignPk})), 최종발령일 = CAST(GETDATE() AS date), 수정일 = GETDATE() WHERE 아이디 = #{userId} AND EXISTS (SELECT 1 FROM J_직원_부서배치 t WHERE t.배치PK = #{assignPk} AND t.직원아이디 = #{userId} AND t.주부서여부 = 1);

INSERT INTO J_직원_발령이력 (아이디, 발령유형, 발령일, 이전부서코드, 사유, 등록일시)
SELECT #{userId}, N'겸직해제',
       ISNULL(#{endDate,jdbcType=DATE}, CAST(GETDATE() AS date)),
       t.부서코드, #{reason,jdbcType=NVARCHAR}, GETDATE()
FROM J_직원_부서배치 t
WHERE t.배치PK = #{assignPk} AND t.직원아이디 = #{userId}
  AND t.종료일 IS NULL AND t.주부서여부 = 0;

UPDATE J_직원_부서배치
SET 종료일 = ISNULL(#{endDate,jdbcType=DATE}, CAST(GETDATE() AS date))
WHERE 배치PK = #{assignPk} AND 직원아이디 = #{userId}
  AND 종료일 IS NULL AND 주부서여부 = 0;
